// Parse, simpan data terakhir + riwayat (maks 50), siapkan payload WebSocket
let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); }
    catch (e) { node.error('Payload sensor bukan JSON valid', msg); return null; }
}
if (typeof data !== 'object' || data === null) return null;

data.received = new Date().toISOString();
flow.set('lastSensor', data);

let history = flow.get('history') || [];
history.push(data);
if (history.length > 50) history = history.slice(-50);
flow.set('history', history);

// Evaluasi threshold (default 30 jika belum pernah diset)
const threshold = flow.get('threshold');
const maxSuhu = (typeof threshold === 'number') ? threshold : 30;
const alert = (typeof data.suhu === 'number') && data.suhu > maxSuhu;
if (alert) node.warn('ALERT: suhu ' + data.suhu + ' melebihi batas ' + maxSuhu);

msg.payload = Object.assign({}, data, {alert: alert, threshold: maxSuhu});
return msg;

// OPSIONAL (node dinonaktifkan): siapkan INSERT untuk node-red-node-sqlite
// Hubungkan input dari 'Simpan Data Sensor' dan output ke node 'sqlite' (mode: Via msg.topic)
const d = msg.payload;
msg.topic = 'INSERT INTO sensor_history (suhu, kelembaban, ts, received) VALUES ($suhu, $kelembaban, $ts, $received)';
msg.payload = {$suhu: d.suhu, $kelembaban: d.kelembaban, $ts: d.timestamp, $received: d.received};
return msg;

