// Autentikasi X-API-Key + router sederhana untuk semua /api/*
const VALID_KEY = 'rahasia123';
msg.headers = {'Access-Control-Allow-Origin': '*'};

const key = msg.req.headers['x-api-key'];
if (key !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key salah atau kosong'};
    return [msg, null, null, null, null];
}

const method = msg.req.method;
const path = (msg.req.path || msg.req.url.split('?')[0]).replace(/\/+$/, '');

if (method === 'GET'  && path === '/api/suhu')      return [null, msg, null, null, null];
if (method === 'GET'  && path === '/api/history')   return [null, null, msg, null, null];
if (method === 'POST' && path === '/api/kontrol')   return [null, null, null, msg, null];
if (method === 'PUT'  && path === '/api/threshold') return [null, null, null, null, msg];

msg.statusCode = 404;
msg.payload = {status: 'error', message: 'Endpoint tidak ditemukan'};
return [msg, null, null, null, null];

const data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
const threshold = flow.get('threshold');
const maxSuhu = (typeof threshold === 'number') ? threshold : 30;
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    data: data,
    alert: (typeof data.suhu === 'number') && data.suhu > maxSuhu,
    threshold: maxSuhu,
    server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

const history = (flow.get('history') || []).slice(-50);
msg.statusCode = 200;
msg.payload = {status: 'success', count: history.length, data: history};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

const body = msg.payload;
msg.headers = {'Access-Control-Allow-Origin': '*'};

if (!body || typeof body !== 'object' ||
    typeof body.device !== 'string' || !body.device.trim() ||
    typeof body.action !== 'string' || !body.action.trim()) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi (string)'};
    return [msg, null];
}

const cmd = {device: body.device.trim(), action: body.action.trim(), sent_at: new Date().toISOString()};
const mqttMsg = {topic: 'iot/kontrol', payload: cmd, qos: 0, retain: false};

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: cmd};
return [msg, mqttMsg];

const body = msg.payload;
msg.headers = {'Access-Control-Allow-Origin': '*'};
const v = (body && body.max_suhu !== undefined && body.max_suhu !== '') ? Number(body.max_suhu) : NaN;

if (!isFinite(v)) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'max_suhu wajib berupa angka'};
    return msg;
}
flow.set('threshold', v);
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Threshold disimpan', max_suhu: v};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Access-Control-Max-Age': '86400'
};
return msg;
